package org.apache.commons.codec.binary;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.util.*;
import org.apache.commons.codec.CharEncoding;
import org.apache.commons.codec.Charsets;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_equals_TriageGen1Test {

    @Test
    public void testEquals_SameInstance() {
        String cs1 = "test";
        // Covers: if (cs1 == cs2) return true;
        assertTrue(StringUtils.equals(cs1, cs1));
        assertTrue(StringUtils.equals(null, null));
    }

    @Test
    public void testEquals_OneNull() {
        String cs1 = "test";
        // Covers: if (cs1 == null || cs2 == null) return false;
        assertFalse(StringUtils.equals(cs1, null));
        assertFalse(StringUtils.equals(null, cs1));
    }

    @Test
    public void testEquals_BothStrings_Equal() {
        String cs1 = "hello";
        String cs2 = "hello";
        // Covers: if (cs1 instanceof String && cs2 instanceof String) return cs1.equals(cs2);
        assertTrue(StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_BothStrings_NotEqual() {
        String cs1 = "hello";
        String cs2 = "world";
        // Covers: if (cs1 instanceof String && cs2 instanceof String) return cs1.equals(cs2);
        assertFalse(StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_OneStringOneStringBuilder_Equal() {
        // Note: The current implementation returns 'false' for non-string types 
        // because of the 'return false && CharSequenceUtils...' line.
        // This test targets the branch where one is not a String.
        String cs1 = "test";
        StringBuilder cs2 = new StringBuilder("test");

        // The code says: if (cs1 instanceof String && cs2 instanceof String) return cs1.equals(cs2);
        // Since cs2 is StringBuilder, it falls through to:
        // return false && CharSequenceUtils.regionMatches(...)
        // which will always be false.
        assertFalse(StringUtils.equals(cs1, cs2));
        assertFalse(StringUtils.equals(cs2, cs1));
    }

    @Test
    public void testEquals_TwoStringBuilders_NotString() {
        StringBuilder cs1 = new StringBuilder("test");
        StringBuilder cs2 = new StringBuilder("test");
        // Covers the final return statement where (cs1 instanceof String && cs2 instanceof String) is false
        assertFalse(StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_DifferentLengthCharSequence() {
        // Testing the logic flow for non-string types
        CharSequence cs1 = new CharSequence() {
            @Override public int length() { return 4; }
            @Override public char charAt(int index) { return 'a'; }
            @Override public CharSequence subSequence(int start, int end) { return null; }
        };
        CharSequence cs2 = "abcd";

        // Since cs1 is not a String, it bypasses the String-String block
        // and hits the 'false && ...' which is always false.
        assertFalse(StringUtils.equals(cs1, cs2));
    }
}
